                                                        {track.coverImageBanner && (
                                                            <span 
                                                                className="absolute -bottom-1 -right-1 bg-blue-600 text-white text-[8px] font-black px-1 py-0.2 rounded shadow-sm"
                                                                title="Đã có banner ngang 16:9"
